    public function down(Schema $schema): void
    {
        $this->abortIf(
            true,
            'This migration restores audited legacy quiz relations and is intentionally irreversible.'
        );
    }

    /**
     * @return list<array{0: int, 1: int, 2: int}>
     */
    private function decodeMappingRows(): array
    {
        $encoded = str_replace(
            ["\r", "\n"],
            '',
            self::MAPPING_GZIP_BASE64
        );
        $compressed = base64_decode($encoded, true);

        if (false === $compressed) {
            throw new RuntimeException(
                'Unable to decode the embedded legacy quiz relation mapping.'
            );
        }

        $raw = gzdecode($compressed);
        if (false === $raw) {
            throw new RuntimeException(
                'Unable to decompress the embedded legacy quiz relation mapping.'
            );
        }

        if (!hash_equals(self::MAPPING_SHA256, hash('sha256', $raw))) {
            throw new RuntimeException(
                'The embedded legacy quiz relation mapping checksum is invalid.'
            );
        }

        $rows = [];
        $pairs = [];
        $quizIds = [];

        foreach (explode("\n", trim($raw)) as $lineNumber => $line) {
            if (
                1 !== preg_match(
                    '/^(\d+)\t(\d+)\t(\d+)$/D',
                    $line,
                    $matches
                )
            ) {
                throw new RuntimeException(sprintf(
                    'Invalid legacy quiz relation mapping row at line %d.',
                    $lineNumber + 1
                ));
            }

            $quizId = (int) $matches[1];
            $questionOrder = (int) $matches[2];
            $questionId = (int) $matches[3];

            if ($quizId <= 0 || $questionOrder < 0 || $questionId <= 0) {
                throw new RuntimeException(sprintf(
                    'Invalid legacy quiz relation values at line %d.',
                    $lineNumber + 1
                ));
            }

            $pairKey = $quizId.':'.$questionId;
            if (isset($pairs[$pairKey])) {
                throw new RuntimeException(sprintf(
                    'Duplicate legacy quiz-question pair at line %d.',
                    $lineNumber + 1
                ));
            }

            $pairs[$pairKey] = true;
            $quizIds[$quizId] = true;
            $rows[] = [$quizId, $questionOrder, $questionId];
        }

        if (
            self::EXPECTED_MAPPING_ROWS !== \count($rows)
            || self::EXPECTED_MAPPING_QUIZZES !== \count($quizIds)
        ) {
            throw new RuntimeException(sprintf(
                'Unexpected legacy quiz mapping size: rows=%d, quizzes=%d.',
                \count($rows),
                \count($quizIds)
            ));
        }

        return $rows;
    }

    /**
     * @param list<array{0: int, 1: int, 2: int}> $rows
     */
    private function queueMappingRows(array $rows): void
    {
        foreach (array_chunk($rows, self::INSERT_BATCH_SIZE) as $batch) {
            $values = [];

            foreach ($batch as [$quizId, $questionOrder, $questionId]) {
                $values[] = sprintf(
                    '(%d, %d, %d)',
                    $quizId,
                    $questionOrder,
                    $questionId
                );
            }

            $this->addSql(
                'INSERT INTO tmp_legacy_quiz_relation_map (
                    quiz_id,
                    question_order,
                    question_id
                 ) VALUES '.implode(', ', $values)
            );
        }
    }

    private function queueDuplicateKeyGuard(string $invalidConditionSql): void
    {
        $this->addSql(
            'INSERT INTO tmp_legacy_quiz_relation_guard (id) '
            .$invalidConditionSql
        );
    }

    private function requireTargetSchema(Schema $schema): void
    {
        $requiredColumns = [
            'c_quiz' => ['iid'],
            'c_quiz_question' => ['iid'],
            'c_quiz_rel_question' => [
                'iid',
                'question_order',
                'question_id',
                'quiz_id',
                'destination',
            ],
        ];

        foreach ($requiredColumns as $tableName => $columns) {
            $this->abortIf(
                !$schema->hasTable($tableName),
                sprintf(
                    'Legacy quiz relation repair requires table %s.',
                    $tableName
                )
            );

            $table = $schema->getTable($tableName);
            foreach ($columns as $columnName) {
                $this->abortIf(
                    !$table->hasColumn($columnName),
                    sprintf(
                        'Legacy quiz relation repair requires column %s.%s.',
                        $tableName,
                        $columnName
                    )
                );
            }
        }
    }

    private function abortOnExternalRelationReferences(): void
    {
        $externalReferences = (int) $this->connection->fetchOne(
            <<<'SQL'
SELECT COUNT(*)
FROM information_schema.KEY_COLUMN_USAGE
WHERE REFERENCED_TABLE_SCHEMA = DATABASE()
  AND REFERENCED_TABLE_NAME = 'c_quiz_rel_question'
  AND REFERENCED_COLUMN_NAME = 'iid'
  AND TABLE_NAME <> 'c_quiz_rel_question'
SQL
        );

        $this->abortIf(
            $externalReferences > 0,
            sprintf(
                'Legacy quiz relation repair refused because %d external foreign keys reference c_quiz_rel_question.iid.',
                $externalReferences
            )
        );
    }
